function firstWeekOfYear(n){let t=new Date(n,0,1),i=t.getDay(),u=i===0?-6:1-i,r=new Date(t);return r.setDate(t.getDate()+u),r}function formatDateNumber(n,t,i){let r=String(t).padStart(2,"0"),u=String(i).padStart(2,"0");return`${n}-${r}-${u}`}function formatDate(n){let t=n.getFullYear(),i=String(n.getMonth()+1).padStart(2,"0"),r=String(n.getDate()).padStart(2,"0");return`${t}-${i}-${r}`}function collectFormData(n,t){let u=n.querySelector(".timeUnit").value;t.append("TimeUnit",u);let i,r;switch(u){case"day":i=n.querySelector(".startDate").value;r=n.querySelector(".endDate").value;break;case"week":i=formatDate(firstWeekOfYear(parseInt(n.querySelector(".startWeekYear").value)).addDays(7*(n.querySelector(".startWeekWeek").value-1)));r=formatDate(firstWeekOfYear(parseInt(n.querySelector(".endWeekYear").value)).addDays(7*(n.querySelector(".endWeekWeek").value-1)));break;case"month":i=formatDateNumber(n.querySelector(".startMonthYear").value,n.querySelector(".startMonthMonth").value,1);r=formatDateNumber(n.querySelector(".endMonthYear").value,n.querySelector(".endMonthMonth").value,1);break;case"quarter":i=formatDateNumber(n.querySelector(".startQuarterYear").value,n.querySelector(".startQuarterQuarter").value*3-2,1);r=formatDateNumber(n.querySelector(".endQuarterYear").value,n.querySelector(".endQuarterQuarter").value*3-2,1);break;case"year":i=formatDateNumber(n.querySelector(".startYearInput").value,1,1);r=formatDateNumber(n.querySelector(".endYearInput").value,1,1)}return t.append("Start",i),t.append("End",r),t}Date.prototype.addDays=function(n){return this.setDate(this.getDate()+n),this};